CREATE TABLE dbo.Dim_Dealer
(
    dealer_id VARCHAR(10) NOT NULL,
    dealer_name VARCHAR(50),
    city VARCHAR(50)
)
WITH
(
    DISTRIBUTION = HASH(dealer_id),
    HEAP
);

