CREATE TABLE dbo.Stg_Dealer
(
    dealer_id VARCHAR(10),
    dealer_name VARCHAR(50),
    city VARCHAR(50)
)
WITH
(
    DISTRIBUTION = ROUND_ROBIN,
    HEAP
);

