---implement scd1 using merge --

MERGE INTO dbo.Dim_Dealer AS T
USING dbo.Stg_Dealer AS S
ON T.dealer_id = S.dealer_id

WHEN MATCHED THEN
    UPDATE SET
        T.dealer_name = S.dealer_name,
        T.city = S.city

WHEN NOT MATCHED BY TARGET THEN
    INSERT (dealer_id, dealer_name, city)
    VALUES (S.dealer_id, S.dealer_name, S.city);


